record.field:
records = env['pt.place.application'].browse(context.get('active_ids', []))
            if not records:
            records = env['pt.place.application'].search([
            ('final_report', '!=', False),
            ('state', 'in', ['approved', 'in_progress', 'completed'])
            ])
            total = len(records)
            processed = 0
            errors = []
            for record in records:
            try:
            if not record.report_text:
            text = record._extract_text(record.final_report, record.report_filename)
            if not text:
            errors.append(f"No text extracted for {record.student_name} (ID: {record.id})")
            continue
            record.report_text = text
            record.plagiarism_results = record._check_plagiarism(record.report_text)
            processed += 1
            except Exception as e:
            errors.append(f"Error for {record.student_name} (ID: {record.id}): {str(e)}")
            env.cr.commit() # Commit after each record to avoid rollback on error
            message = f"Processed {processed}/{total} records."
            if errors:
            message += f"\nErrors:\n" + "\n".join(errors)
            return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
            'title': 'Bulk Plagiarism Check Completed',
            'message': message,
            'type': 'success' if not errors else 'warning',
            'sticky': True,
            }
            }
